python - <<'EOF'
p='css/deck.css'
s=open(p,encoding='utf-8').read()

# 1. new moods + swap pop, after the shades mood
anchor='.marvin-hud[data-mood="shades"] .mv-shades { transform: scaleY(1); opacity: 1; }\n'
assert anchor in s
moods = anchor + '''
.marvin-hud[data-mood="shrug"] .marvin-svg { transform: rotate(-4deg); }
.marvin-hud[data-mood="shrug"] .mv-eye-l { transform: scaleY(0.55); }
.marvin-hud[data-mood="shrug"] .mv-eye-r { transform: scaleY(0.5) scaleX(0.85); }
.marvin-hud[data-mood="shrug"] .mv-emote::before { content: "~"; }

.marvin-hud[data-mood="sleepy"] .marvin-svg { transform: rotate(4deg) translateY(3px); }
.marvin-hud[data-mood="sleepy"] .mv-eye { fill: #a9bec4; }
.marvin-hud[data-mood="sleepy"] .mv-eye-l { transform: scaleY(0.12); }
.marvin-hud[data-mood="sleepy"] .mv-eye-r { transform: scaleY(0.14); }
.marvin-hud[data-mood="sleepy"] .mv-emote::before { content: "zzz"; color: var(--text-dim); }

.marvin-hud[data-mood="heart"] .mv-eye-l { transform: scaleY(0.5) translateY(-3px); }
.marvin-hud[data-mood="heart"] .mv-eye-r { transform: scaleY(0.72); }
.marvin-hud[data-mood="heart"] .mv-emote::before { content: "\\2665"; font-size: 1.15em; }

.marvin-hud[data-mood="party"] .mv-shades { transform: scaleY(1); opacity: 1; }
.marvin-hud[data-mood="party"] .marvin-svg { animation: marvin-jitter 0.3s linear infinite; }
.marvin-hud[data-mood="party"] .mv-emote::before { content: "\\1F389"; font-size: 1.2em; }
.marvin-hud[data-mood="party"] .marvin-say { color: var(--text); border-color: var(--accent); }

/* a beat swap: the bubble pops so the reversal reads as a new line */
.marvin-hud.is-swapping .marvin-say { animation: say-pop 0.32s var(--ease-out); }
@keyframes say-pop {
  0%   { transform: scale(0.92); opacity: 0.4; }
  100% { transform: none; opacity: 1; }
}
'''
s=s.replace(anchor, moods)

# 2. party rain + spin, before the reduced-motion block
anchor2='/* ============================================================\n   Reduced motion'
assert anchor2 in s
party='''/* ============================================================
   Marvin party (M key) — visors rain, the big Marvin spins
   ============================================================ */
#party {
  position: fixed; inset: 0; z-index: 44; pointer-events: none; overflow: hidden;
}
#party .party-visor {
  position: absolute; top: -120px; left: var(--x);
  width: var(--size);
  animation: party-fall var(--dur) linear var(--delay) infinite;
}
@keyframes party-fall {
  from { transform: translateY(0) rotate(0deg); opacity: 0; }
  8%   { opacity: 1; }
  to   { transform: translateY(118vh) rotate(var(--rot)); opacity: 1; }
}
body.party .close-marvin .marvin { animation: marvin-spin 1.1s linear infinite; }
body.party .marvin-halo { animation: halo-pulse 0.55s ease-in-out infinite alternate; }
body.party .marvin-wave { animation-duration: 0.5s; }
@keyframes marvin-spin { to { transform: rotate(360deg); } }
@keyframes halo-pulse { from { transform: scale(0.9); opacity: 0.7; } to { transform: scale(1.35); opacity: 1; } }

'''
s=s.replace(anchor2, party+anchor2)

# 3. hands-up list on the act divider
anchor3='.s-act .sub { margin-top: 0.8rem; }\n'
assert anchor3 in s
hands=anchor3+'''.hands-up {
  list-style: none; margin-top: 2.4rem;
  display: flex; flex-direction: column; gap: 0.55rem;
  font-family: var(--font-mono); font-size: clamp(0.95rem, 1.35vw, 1.25rem);
  color: var(--text-muted); letter-spacing: 0.01em;
}
.hands-up li::before { content: "\\270B  "; }
.hands-up li:first-child { color: var(--text); }
.hands-up li:last-child { color: var(--accent); }
'''
s=s.replace(anchor3, hands)

# 4. git panel red glyph
anchor4='.git-panel .q { color: var(--text); }\n'
assert anchor4 in s
s=s.replace(anchor4, anchor4+'.git-panel .x { color: var(--red); }\n.git-panel .why { padding-top: 0.2rem; margin-top: 0.3rem; border-top: 1px dashed var(--border); }\n')

# 5. demo sub line centered
anchor5='.s-demo { text-align: center; }\n'
assert anchor5 in s
s=s.replace(anchor5, anchor5+'.s-demo .sub { margin: 0 auto; color: var(--text-dim); font-style: italic; }\n')

# 6. not-list: 8 items fit — tighten gap a touch
s=s.replace('.not-list { list-style: none; margin-top: 2.2rem; display: grid; grid-template-columns: 1fr 1fr; gap: 0.7rem 2.4rem; }',
            '.not-list { list-style: none; margin-top: 2rem; display: grid; grid-template-columns: 1fr 1fr; gap: 0.6rem 2.4rem; }')

# 7. reduced motion: stop the party too
s=s.replace('  .stage-glow { animation: none; }\n', '  .stage-glow { animation: none; }\n  #party { display: none; }\n')

open(p,'w',encoding='utf-8',newline='\n').write(s)
print('css ok')
EOF

